<template>
  <section ref="screen" class="weather-screen">
    <div ref="globe" class="screen-globe"></div>
    <div class="screen-context"><span>起报 {{ cycleLabel }} UTC</span><span>有效 {{ fmt(field.validTime) }}</span><b>+{{ lead }}h</b><span>{{ mode === 'probability' ? '集合降水概率' : selectedName }}</span><span v-if="activeScene">模型：{{ activeScene }}</span></div>
    <aside v-show="leftOpen" class="screen-panel screen-left">
      <div class="panel-heading"><h3>场景控制</h3><button @click="leftOpen=false" aria-label="收起左侧面板">‹</button></div>
      <nav class="panel-tabs" aria-label="场景控制页签"><button v-for="tab in leftTabs" :key="tab.key" :aria-pressed="leftTab===tab.key" @click="leftTab=tab.key">{{ tab.name }}</button></nav>
      <div class="panel-scroll">
        <section v-show="leftTab==='forecast'">
          <label>场景模式<select v-model="mode"><option value="forecast">确定性预报</option><option value="probability">集合降水概率</option></select></label>
          <label v-if="mode==='forecast'">气象要素<select v-model="variable"><option v-for="v in variables" :key="v.key" :value="v.key">{{ v.name }} · {{ v.unit }}</option></select></label>
          <label v-if="mode==='forecast' && variable==='tp'">累计口径<select v-model="accumulation"><option value="6h">6小时累计</option><option value="24h" :disabled="lead<24">24小时累计</option><option value="total">起报至当前累计</option></select></label>
          <label v-if="mode==='probability'">概率阈值<select v-model.number="threshold"><option v-for="t in [1,5,10,20,50]" :key="t" :value="t">≥ {{ t }} mm / 6h</option></select></label>
          <div class="data-description"><span>当前预报批次</span><b>{{ info.modelProduct || '--' }}</b><span>{{ cycleLabel }} UTC</span></div><p class="screen-note">时间轴控制预报有效时间。气象场是预报产品，卫星底图不是实时观测。</p>
        </section>
        <section v-show="leftTab==='region'"><BuildingCoveragePanel :regions="buildingRegions" :state="regionalState" v-model:enabled="regionalEnabled" v-model:outlines="coverageOutlines" :message="regionalMessage" :error="catalogError" @locate="locateBuildingRegion" @retry="retryRegionalBuildings"/>
          <div class="city-entry"><span class="entry-eyebrow">竞赛重点场景 · 本地模型</span><h4>上海陆家嘴</h4><p>开放建筑轮廓与高度，展示高层建筑群。模型随系统提供，无需在线下载。</p><button :disabled="initializing || buildingBusy" @click="openCity(false)">{{ buildingBusy ? '正在打开…' : '进入立体城区' }}</button><button :disabled="initializing || buildingBusy" @click="openCity(true)">离线稳定演示</button><button @click="home" :disabled="initializing">返回全国气象</button><small>简化建筑 · 部分高度估算 · 示意外立面</small></div><label>区域搜索<input v-model="regionSearch" placeholder="输入省份名称" aria-label="区域搜索"></label>
          <div class="screen-region-list"><button v-for="p in filteredProvinces" :key="p.name" @click="selectRegion(p)">{{ p.name }}<span>›</span></button></div><p v-if="!filteredProvinces.length" class="screen-note">没有匹配的区域</p><p class="screen-note">选择区域后定位到省级中心，并展开该中心格点预报；不代表全省统计。</p>
        </section>
        <section v-show="leftTab==='layers'">
          <label>显示质量<select v-model="quality" aria-label="显示质量"><option value="fast">流畅 · 减少细节请求</option><option value="balanced">均衡（推荐）</option><option value="fine">精细 · 更多加载时间</option></select></label><label>影像来源<select v-model="basemap" aria-label="影像来源"><option value="city">ArcGIS 城市高清影像</option><option value="satellite">Sentinel-2 全国影像</option><option value="offline">本地基础底图（离线）</option></select></label>
          <button v-if="lastMapError" @click="retryImagery">重试城市高清影像</button><label class="screen-check"><input type="checkbox" v-model="terrainEnabled">真实地形高程（默认开启）</label><p class="screen-note terrain-state">{{ terrainStatus }}</p><button v-if="terrainEnabled && terrainStatus.includes('不可用')" @click="loadTerrain">重试地形</button><h4>建筑模型</h4><label class="screen-check"><input type="checkbox" v-model="regionalEnabled">随视角加载已接入区域建筑</label><p class="screen-note">{{ regionalMessage }}</p><label class="screen-check"><input type="checkbox" v-model="buildingsVisible">建筑模型</label><div v-if="activeScene" class="model-actions"><button @click="focusModel()">定位模型</button><button @click="removeModel">卸载模型</button></div><label>模型高程偏移（米）<input type="number" step="1" v-model.number="modelHeightOffset" aria-label="模型高程偏移"></label><label>3D Tiles 模型地址<input v-model="modelUrl" placeholder="https://…/tileset.json 或 /models/…"></label><button :disabled="buildingBusy || !modelUrl.trim()" @click="loadCustomModel()">加载并定位模型</button><p class="screen-note">{{ buildingStatus }}<br>可加载自有 3D Tiles 模型；在线资源需联网。</p><h4>业务图层</h4>
          <label class="screen-check"><input type="checkbox" v-model="weatherVisible">气象格点场</label><label class="screen-check"><input type="checkbox" v-model="smooth">平滑显示（仅视觉插值）</label><label class="screen-check"><input type="checkbox" v-model="boundariesVisible">省级边界</label><label class="screen-check"><input type="checkbox" v-model="placesVisible">省级中心</label>
          <label>气象场不透明度 <b>{{ Math.round(opacity*100) }}%</b><input type="range" min="0" max="1" step="0.05" v-model.number="opacity"></label><p class="screen-note">{{ mapStatus }}<br><span v-if="lastMapError">{{ lastMapError }}<br></span>{{ terrainStatus }}<br>平滑显示不增加预报精度。</p>
        </section>
      </div>
    </aside>
    <button v-if="!leftOpen" class="screen-reopen left" @click="leftOpen=true">场景控制 ›</button>
    <button class="screen-compass" @click="home" title="复位至中国" aria-label="指北针复位"><span :style="{transform:`rotate(${-heading}deg)`}">N<br>↑</span><small>{{ Math.round(heading)%360 }}°</small></button>
    <section v-if="cityActive && modelFocused && !rightOpen" class="city-card" aria-label="城区场景信息"><span class="entry-eyebrow">本地建筑 / 道路示意底图{{ offlineCity ? ' · 离线' : '' }}</span><h3>上海陆家嘴</h3><p>{{ cityManifest?.count || '--' }} 个建筑 / 部件 · 最高 {{ cityManifest?.maxHeight || '--' }} m</p><p>OSM 标注高度 {{ cityManifest?.heights?.['OSM height'] || '--' }} 个<br>其余按层数估算或采用 12m 示意高度</p><label class="city-ground-choice">城区底图<select v-model="cityGroundMode" aria-label="城区底图"><option value="schematic">同源道路示意图（推荐）</option><option value="imagery" :disabled="offlineCity">卫星影像（可能存在楼顶投影差）</option></select></label><p class="city-ground-status">{{ cityGroundStatus }}</p><small>窗格为示意材质，非实景摄影。<br>近景预报仍使用原始气象格点，不是楼宇级预测。</small><button @click="queryPoint(121.501,31.236,'陆家嘴附近预报格点')">查看城区预报</button><button @click="home">返回全国气象</button><a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap contributors · ODbL</a></section><div v-if="!rightOpen && !(cityActive && modelFocused)" class="compact-summary"><span>全国场 · {{ field.unit || '--' }}</span><b>{{ num(field.statistics?.maximum) }} <small>最大</small></b><button @click="openAnalysis('overview')">展开分析 ›</button></div>
    <aside v-show="rightOpen" class="screen-panel screen-right">
      <div class="panel-heading"><h3>{{ rightTab==='point' ? locationLabel : rightTab==='risk' ? '预报风险' : '全国态势' }}</h3><button @click="rightOpen=false" aria-label="收起右侧面板">×</button></div>
      <nav class="panel-tabs" aria-label="分析页签"><button :aria-pressed="rightTab==='overview'" @click="openAnalysis('overview')">全国</button><button :aria-pressed="rightTab==='point'" @click="openAnalysis('point')">单点</button><button :aria-pressed="rightTab==='risk'" @click="openAnalysis('risk')">风险</button></nav>
      <div class="panel-scroll">
        <section v-show="rightTab==='overview'"><p class="screen-note">当前帧 · 全国场统计 · {{ field.unit }}</p><div class="screen-metrics"><div><span>最大值</span><b>{{ num(field.statistics?.maximum) }}</b></div><div><span>平均值</span><b>{{ num(field.statistics?.average) }}</b></div></div><h4>省级中心邻域降水排行</h4><p class="screen-note">{{ field.accumulationLabel || '切换降水查看' }}</p><div v-if="field.ranking?.length" class="screen-rank"><button v-for="(r,i) in field.ranking.slice(0,5)" :key="r.name" @click="focusRanking(r)"><span>{{ i+1 }}　{{ r.name }}</span><b>{{ num(r.value) }} {{ field.unit }}</b></button></div><p v-else class="screen-note">当前图层不提供区域降水排行。</p></section>
        <section v-show="rightTab==='point'"><p class="screen-note">{{ locationLabel }}<br>{{ selectedPoint ? selectedPoint.lon.toFixed(2)+'°E / '+selectedPoint.lat.toFixed(2)+'°N' : '请在地图上点击位置，或在区域页选择省份' }}</p><h4>{{ variableName }} · 确定性格点预报</h4><p v-if="pointLoading" class="screen-note">正在读取逐时效曲线…</p><p v-if="pointError" class="screen-error">{{ pointError }}</p><div ref="chartEl" class="screen-chart"></div><p class="screen-note">该曲线对应选中位置的最近格点，不是区域平均值。</p><button class="screen-link" :disabled="!selectedPoint" @click="$emit('point-selected',selectedPoint)">进入单点详情 ↗</button></section>
        <section v-show="rightTab==='risk'"><p class="screen-note">整批次 · 24小时滑动累计峰值<br>不是当前帧、当前选中地点的风险等级</p><p v-if="riskError" class="screen-error">{{ riskError }}</p><template v-else><div class="screen-risk">{{ risk.peak?.level || '待加载' }}<b>{{ num(risk.peak?.maximum) }} <small>mm/24h</small></b></div><p class="screen-note">峰值时效 +{{ risk.peak?.leadHour ?? '--' }}h<br>{{ risk.peak?.hotspot?.nearestRegion || '--' }}附近</p></template></section>
      </div>
    </aside>
    <div class="screen-tools" role="toolbar" aria-label="场景工具"><button @click="openLeft('layers')" :aria-pressed="leftOpen && leftTab==='layers'"><AppIcon name="layers" :size="20"/><span>图层</span></button><button @click="openLeft('region')" :aria-pressed="leftOpen && leftTab==='region'"><AppIcon name="locate" :size="20"/><span>区域定位</span></button><button @click="oblique" :disabled="initializing"><AppIcon name="globe" :size="20"/><span>倾斜视角</span></button><button @click="topDown" :disabled="initializing"><AppIcon name="target" :size="20"/><span>俯视</span></button><button @click="tourOpen=!tourOpen" :aria-pressed="tourOpen"><AppIcon name="play" :size="20"/><span>巡航</span></button><button @click="home" :disabled="initializing"><AppIcon name="refresh" :size="20"/><span>复位</span></button></div>
    <section v-if="tourOpen" class="tour-popover" aria-label="巡航设置"><div class="panel-heading"><h3>演示巡航</h3><button @click="tourOpen=false" aria-label="关闭巡航设置">×</button></div><p class="screen-note">全国 → 四川 → 北京等省级中心；场景按下鼠标可接管视角。</p><label>镜头停留<select v-model.number="tourInterval"><option :value="7000">7秒 / 站</option><option :value="10000">10秒 / 站</option><option :value="15000">15秒 / 站</option></select></label><div class="tour-actions"><button @click="toggleTour" :disabled="initializing">{{ touring ? '暂停巡航' : '开始巡航' }}</button><button @click="mountains" :disabled="initializing">山地实景</button></div></section>
    <div v-if="!initializing && tileState.phase!=='ready'" class="screen-map-loading" :class="{warning:tileState.phase==='warning'}" role="status"><span>{{ resourceLabel }}</span><button v-if="tileState.phase==='warning'" @click="retryResources">重试资源</button></div><div v-if="loading || initializing" class="screen-loading">{{ initializing ? '正在初始化三维场景…' : '正在读取 +'+lead+'h 气象场…' }}</div><div v-if="error" class="screen-alert" role="alert">{{ error }} <button @click="refresh">重试</button></div>
    <div class="screen-legend" v-if="weatherVisible && field.palette?.length && !error"><b>{{ field.name || selectedName }} · {{ field.unit }}</b><div><i v-for="(c,i) in field.palette" :key="i" :style="{background:c}"></i></div><span>{{ num(scaleMin) }}<em>{{ num(scaleMax) }}</em></span></div>
    <footer class="screen-timeline"><div class="timeline-controls"><button :disabled="loading || !leads.length" @click="togglePlayback">{{ playing ? '暂停' : '播放' }}</button><button :disabled="loading" @click="step(-1)" aria-label="上一帧">‹</button><b>+{{ lead }}h</b><button :disabled="loading" @click="step(1)" aria-label="下一帧">›</button><select v-model.number="speed" aria-label="播放速度"><option :value="1500">1.5秒 / 帧</option><option :value="3000">3秒 / 帧</option><option :value="6000">6秒 / 帧</option></select><input aria-label="预报时间轴" type="range" min="0" :max="Math.max(0,leads.length-1)" :value="leadIndex" :disabled="!leads.length" @input="scrub($event)"><span>有效 {{ fmt(field.validTime) }}</span></div><div class="timeline-status"><span>{{ coords || '左键选点 · 拖动旋转 · 滚轮缩放' }}</span><span>预报产品演示 · 非正式气象发布</span></div></footer>
  </section>
</template>
<script setup>
import { ref, computed, watch, onMounted, onBeforeUnmount, nextTick } from 'vue'
import * as C from 'cesium'
import 'cesium/Build/Cesium/Widgets/widgets.css'
import * as echarts from 'echarts'
import china from '../assets/china.json'
import { api } from '../api.js'
import AppIcon from './AppIcon.vue'
import BuildingCoveragePanel from './BuildingCoveragePanel.vue'
import {validateBuildingCatalog,selectBuildingRegions} from '../scene/regionalBuildings.js'
import {createCesiumRegionalBuildings,captureBuildingView} from '../scene/cesiumRegionalBuildings.js'
import { createTileLoadState } from '../scene/tileLoadState.js'
import { rasterize } from '../scene/weatherTexture.js'

const props=defineProps({info:{type:Object,default:()=>({})},fullscreenActive:{type:Boolean,default:false}})
const emit=defineEmits(['point-selected','toggle-fullscreen'])
const screen=ref(),globe=ref(),chartEl=ref(),now=ref(''),full=computed(()=>props.fullscreenActive)
const leftOpen=ref(true),rightOpen=ref(false),initializing=ref(true),loading=ref(false),error=ref('')
const mode=ref('forecast'),variable=ref('tp'),accumulation=ref('6h'),threshold=ref(10),lead=ref(24),leads=ref([]),variables=ref([]),provinces=ref([]),field=ref({}),risk=ref({}),riskError=ref('')
const weatherVisible=ref(true),boundariesVisible=ref(true),placesVisible=ref(true),opacity=ref(.55),heading=ref(0),coords=ref('')
const playing=ref(false),touring=ref(false),speed=ref(3000),pointLoading=ref(false),pointError=ref(''),selectedPoint=ref(null),locationLabel=ref('尚未选点')
let viewer,handler,weatherLayer,boundaries,places,marker,chart,resizeObserver,clockTimer,playTimer,tourTimer,disposed=false,fieldSeq=0,pointSeq=0,tourIndex=0
const cache=new Map()
const leftTab=ref('forecast'),rightTab=ref('overview'),regionSearch=ref(''),tourOpen=ref(false),tourInterval=ref(7000)
const leftTabs=[{key:'forecast',name:'预报'},{key:'region',name:'区域'},{key:'layers',name:'图层'}]
const filteredProvinces=computed(()=>provinces.value.filter(p=>p.name.includes(regionSearch.value.trim())))
function openLeft(tab){leftTab.value=tab;leftOpen.value=true}
async function openAnalysis(tab){rightTab.value=tab;rightOpen.value=true;await nextTick();chart?.resize()}

const offlineStart=new URLSearchParams(location.search).get('sceneOffline')==='1'
const basemap=ref(offlineStart?'offline':'city'),terrainEnabled=ref(!offlineStart),smooth=ref(true),mapStatus=ref('卫星影像正在连接…'),terrainStatus=ref('地形高程正在连接…'),lastMapError=ref('')
const quality=ref('balanced'),tileState=ref({pending:0,phase:'ready',entries:[]}),tileTracker=createTileLoadState()
const buildingRegions=ref([]),regionalState=ref({entries:[],loaded:0,visible:0,loading:0,failed:0}),regionalEnabled=ref(true),coverageOutlines=ref(false),catalogError=ref(''),regionalMessage=ref('建筑覆盖目录正在读取…')
let regionalManager,regionalTimer,coverageSource,regionalMoveEnd
function updateRegionalBuildings(){
 if(!viewer||disposed||!regionalManager)return;
 const view=captureBuildingView(viewer,regionalEnabled.value&&buildingsVisible.value,!!buildingTileset||buildingBusy.value);
 regionalManager.update(view);regionalManager.align();
 const candidates=selectBuildingRegions(buildingRegions.value,{...view,enabled:true,suspended:false},2);
 regionalMessage.value=!regionalEnabled.value?'自动加载已关闭':view.suspended?'重点场景 / 自有模型展示中，自动建筑暂停':view.height>60000?'全国视角 · 放大到城区后加载建筑':!candidates.length?'当前视野暂无已接入建筑数据':regionalState.value.loading?'正在加载视野内建筑…':regionalState.value.failed?'部分区域加载失败，可重试':`当前显示 ${regionalState.value.visible} 个区域建筑`;
}
async function initRegionalBuildings(){
 regionalManager=createCesiumRegionalBuildings(viewer,{getQuality:()=>quality.value,onChange:s=>{if(!disposed)regionalState.value=s}});
 try{const response=await withDeadline(fetch('/buildings/catalog.json'),8000);if(!response.ok)throw Error('建筑目录不可用');const result=validateBuildingCatalog(await response.json(),location.origin);if(disposed)return;buildingRegions.value=result.regions;catalogError.value=result.warnings.join('；');regionalManager.setCatalog(result.regions);
 coverageSource=new C.CustomDataSource('building-coverage');for(const r of result.regions){const [w,s,e,n]=r.bounds;coverageSource.entities.add({id:'coverage-'+r.id,polyline:{positions:C.Cartesian3.fromDegreesArray([w,s,e,s,e,n,w,n,w,s]),width:2,clampToGround:true,material:C.Color.CYAN.withAlpha(.75)}})}coverageSource.show=coverageOutlines.value;await viewer.dataSources.add(coverageSource);
 }catch(e){if(!disposed)catalogError.value='建筑覆盖目录：'+e.message}
 if(disposed)return;regionalMoveEnd=viewer.camera.moveEnd.addEventListener(updateRegionalBuildings);regionalTimer=setInterval(updateRegionalBuildings,1000);updateRegionalBuildings();
}
async function locateBuildingRegion(region){
 stopTour();if(buildingTileset)await removeModel();if(disposed)return;regionalEnabled.value=true;buildingsVisible.value=true;modelFocused.value=false;rightOpen.value=false;weatherVisible.value=false;const radius=Math.max(1500,(region.bounds[2]-region.bounds[0])*90000,(region.bounds[3]-region.bounds[1])*111000);viewer.camera.flyToBoundingSphere(new C.BoundingSphere(C.Cartesian3.fromDegrees(...region.center,100),radius/2),{offset:new C.HeadingPitchRange(C.Math.toRadians(315),C.Math.toRadians(-30),Math.min(45000,radius*1.3)),duration:1.5});coords.value=region.name+' · 按视角自动加载建筑';
}
function retryRegionalBuildings(){regionalManager?.retry();updateRegionalBuildings()}

watch(coverageOutlines,v=>{if(coverageSource){coverageSource.show=v;viewer?.scene.requestRender()}})
let statusTimer
const resourceLabel=computed(()=>tileState.value.phase==='warning'?'部分资源超时或失败，已加载内容可继续使用':tileState.value.phase==='loading'?'加载场景资源 · 待完成 '+tileState.value.pending+' 项':'当前视角资源已就绪')
function updateStatus(){tileState.value=tileTracker.snapshot()}
function applyQuality(){if(!viewer)return;const q={fast:[7,16],balanced:[4,8],fine:[2,3]}[quality.value];viewer.scene.globe.maximumScreenSpaceError=q[0];if(buildingTileset)buildingTileset.maximumScreenSpaceError=q[1];viewer.scene.requestRender()}
watch(quality,()=>{applyQuality();regionalManager?.applyQuality()})
function retryImagery(){tileTracker.reset('globe');if(basemap.value!=='city')basemap.value='city';else loadBasemap()}
function retryResources(){tileTracker.reset('globe');tileTracker.reset('model');updateStatus();loadBasemap();if(terrainEnabled.value)loadTerrain();if(buildingTileset){if(cityActive.value)openCity(offlineCity.value);else loadCustomModel(activeScene.value||'自有模型')}}
let satelliteLayer,terrainProvider,mapSeq=0,terrainSeq=0,terrainFailures=0,baseLayer
function oblique(){if(buildingTileset && modelFocused.value){focusModel();return}stopTour();const target=C.Cartographic.fromCartesian(viewer.camera.positionWC);const centre=selectedPoint.value||{lon:C.Math.toDegrees(target.longitude),lat:C.Math.toDegrees(target.latitude)};viewer.camera.flyToBoundingSphere(new C.BoundingSphere(C.Cartesian3.fromDegrees(centre.lon,centre.lat),1000),{offset:new C.HeadingPitchRange(0,C.Math.toRadians(-40),selectedPoint.value?180000:4500000),duration:1.6})}
function topDown(){if(buildingTileset && modelFocused.value){focusModel(true);return}stopTour();const p=selectedPoint.value||{lon:105,lat:32};viewer.camera.flyTo({destination:C.Cartesian3.fromDegrees(p.lon,p.lat,selectedPoint.value?250000:14000000),orientation:{heading:0,pitch:-Math.PI/2,roll:0},duration:1.5})}
function mountains(){if(cityBaseLayer)cityBaseLayer.show=false;modelFocused.value=false;stopTour();viewer.camera.flyToBoundingSphere(new C.BoundingSphere(C.Cartesian3.fromDegrees(103.35,30.95,1800),1000),{offset:new C.HeadingPitchRange(C.Math.toRadians(25),C.Math.toRadians(-25),45000),duration:2});coords.value='四川龙门山 · 地形展示视角';weatherVisible.value=false}

async function withDeadline(promise,ms,cleanup=()=>{}){let expired=false,timer;try{return await Promise.race([promise.then(value=>{if(expired){cleanup(value);throw new Error('请求已超时')}return value}),new Promise((_,reject)=>{timer=setTimeout(()=>{expired=true;reject(new Error('连接超时，请重试'))},ms)})])}finally{clearTimeout(timer)}}

async function loadBasemap(){
 const seq=++mapSeq;if(!viewer)return
 if(basemap.value==='offline'){if(satelliteLayer){viewer.imageryLayers.remove(satelliteLayer,true);satelliteLayer=null}mapStatus.value='本地基础底图 · 离线模式';viewer.scene.requestRender();return}
 const city=basemap.value==='city';mapStatus.value=city?'城市高清影像连接中…':'Sentinel-2 影像连接中…'
 try{
 const provider=city?await withDeadline(C.ArcGisMapServerImageryProvider.fromUrl('/scene-assets/imagery/',{enablePickFeatures:false}),15000):new C.UrlTemplateImageryProvider({url:'https://tiles.maps.eox.at/wmts/1.0.0/s2cloudless-2024_3857/default/g/{z}/{y}/{x}.jpg',maximumLevel:14,credit:new C.Credit('EOxCloudless © EOX IT Services GmbH · modified Copernicus Sentinel data 2024 · CC BY-NC-SA 4.0',true)})
 const image=await Promise.race([provider.requestImage(0,0,0),new Promise((_,reject)=>setTimeout(()=>reject(new Error('影像连接超时')),15000))]);if(!image)throw new Error('无有效影像瓦片');if(disposed||seq!==mapSeq)return
 const next=viewer.imageryLayers.addImageryProvider(provider,1);next.brightness=1;if(city)lastMapError.value='';const old=satelliteLayer;satelliteLayer=next;if(old)viewer.imageryLayers.remove(old,true);mapStatus.value=city?'ArcGIS World Imagery · 城市近景（清晰度因地区而异）':'Sentinel-2 2024 · 全国影像';let failures=0
 provider.errorEvent.addEventListener(tileError=>{if(disposed||seq!==mapSeq)return;tileError.retry=tileError.timesRetried<1;if(!tileError.retry)tileTracker.fail('globe');updateStatus();if(++failures>=6)lastMapError.value='部分影像瓦片暂不可用，保留已加载高清影像，可点击重试'});viewer.scene.requestRender()
 }catch(e){if(!disposed&&seq===mapSeq){tileTracker.fail('globe');updateStatus();lastMapError.value=(city?'城市高清影像':'全国影像')+'不可用：'+e.message;mapStatus.value=lastMapError.value;basemap.value=city?'satellite':'offline'}}
}
async function loadTerrain(){
 const seq=++terrainSeq;if(!viewer)return
 if(!terrainEnabled.value){viewer.terrainProvider=new C.EllipsoidTerrainProvider();terrainStatus.value='地形已关闭';alignCityGround();viewer.scene.requestRender();return}
 terrainStatus.value='默认地形 · 正在连接真实高程…'
 try{const provider=terrainProvider||await Promise.race([C.ArcGISTiledElevationTerrainProvider.fromUrl('https://elevation3d.arcgis.com/arcgis/rest/services/WorldElevation3D/Terrain3D/ImageServer'),new Promise((_,reject)=>setTimeout(()=>reject(new Error('连接超时')),15000))]);if(disposed||seq!==terrainSeq)return;terrainProvider=provider;viewer.terrainProvider=provider;terrainStatus.value='ArcGIS Terrain3D · 真实高程已启用';alignCityGround();provider.errorEvent.addEventListener(e=>{if(disposed||seq!==terrainSeq)return;e.retry=e.timesRetried<1;if(!e.retry)tileTracker.fail('globe');terrainStatus.value='真实高程已启用 · 部分高程瓦片不可用';updateStatus()});viewer.scene.requestRender()}catch(e){if(!disposed&&seq===terrainSeq){tileTracker.fail('globe');updateStatus();terrainStatus.value='地形不可用：'+e.message+' · 暂用椭球面，可重试'}}
}

const buildingsVisible=ref(true),buildingStatus=ref('未加载建筑；可从区域页进入陆家嘴本地场景'),buildingBusy=ref(false),modelUrl=ref('')
let buildingLayer,buildingTileset,buildingSeq=0
const modelHeightOffset=ref(0),activeScene=ref(''),modelFocused=ref(false),cityManifest=ref(null)
let cityBaseLayer,cityGroundSeq=0,cityGroundOffset=0
const cityGroundMode=ref('schematic'),cityGroundStatus=ref('')
const offlineCity=ref(false)
const cityActive=computed(()=>activeScene.value==='上海陆家嘴')
async function openCity(offline=false){
 if(buildingBusy.value||!viewer)return;regionalManager?.update({enabled:false});stopTour();stopPlayback();const wasOffline=offlineCity.value;offlineCity.value=offline===true;if(!offlineCity.value&&wasOffline){basemap.value='city';terrainEnabled.value=true}if(offlineCity.value){cityGroundMode.value='schematic';basemap.value='offline';terrainEnabled.value=false;tileTracker.reset('globe');updateStatus()}
 try{const response=await withDeadline(fetch('/buildings/lujiazui/manifest.json'),8000);if(!response.ok)throw Error('本地城区说明文件缺失');const manifest=await response.json();if(disposed)return;cityManifest.value=manifest;if(!cityBaseLayer){const base=new C.SingleTileImageryProvider({url:'/buildings/lujiazui/context.png',rectangle:C.Rectangle.fromDegrees(121.484,31.222,121.520,31.250),tileWidth:2048,tileHeight:2048});cityBaseLayer=viewer.imageryLayers.addImageryProvider(base);cityBaseLayer.show=false}modelUrl.value='/buildings/lujiazui/tileset.json';modelHeightOffset.value=0;buildingsVisible.value=true;await loadCustomModel('上海陆家嘴');if(cityActive.value&&!disposed){focusModel();syncCityGround();if(baseLayer){baseLayer.show=true;baseLayer.brightness=offlineCity.value ? .18 : .8}placesVisible.value=false;boundariesVisible.value=false;leftOpen.value=false;coords.value='陆家嘴 · 本地建筑模型 · 部分高度估算 · 示意外立面'}}catch(e){if(!disposed)buildingStatus.value='本地城区加载失败：'+e.message}
}
function syncCityGround(){if(cityBaseLayer)cityBaseLayer.show=cityActive.value&&modelFocused.value&&cityGroundMode.value==='schematic';viewer?.scene.requestRender()}
watch(cityGroundMode,syncCityGround)
async function alignCityGround(){
 const seq=++cityGroundSeq;if(!viewer||!cityActive.value||!buildingTileset)return;
 cityGroundOffset=-5;cityGroundStatus.value='模型地面已对齐椭球面';offsetModel();
 if(!terrainEnabled.value||viewer.terrainProvider instanceof C.EllipsoidTerrainProvider)return;
 cityGroundStatus.value='正在适配城区中心地形高程…';
 try{const points=await withDeadline(C.sampleTerrain(viewer.terrainProvider,12,[C.Cartographic.fromDegrees(121.501,31.236)]),8000);if(disposed||seq!==cityGroundSeq||!cityActive.value)return;const h=points[0].height;if(!Number.isFinite(h))throw Error('无有效高程');cityGroundOffset=h-5;offsetModel();cityGroundStatus.value='已按城区中心地形对齐 · 局部地面仍可能有高差'}catch(e){if(!disposed&&seq===cityGroundSeq)cityGroundStatus.value='地形采样不可用 · 暂按椭球面，支持手动高程偏移'}
}
function offsetModel(){if(!buildingTileset||!viewer)return;const c=buildingTileset.boundingSphere.center;const geo=C.Cartographic.fromCartesian(c);const ground=C.Cartesian3.fromRadians(geo.longitude,geo.latitude,geo.height);const elevated=C.Cartesian3.fromRadians(geo.longitude,geo.latitude,geo.height+cityGroundOffset+(Number(modelHeightOffset.value)||0));buildingTileset.modelMatrix=C.Matrix4.fromTranslation(C.Cartesian3.subtract(elevated,ground,new C.Cartesian3()));viewer.scene.requestRender()}
watch(modelHeightOffset,offsetModel)
function focusModel(top=false){if(!buildingTileset||!viewer)return;modelFocused.value=true;stopTour();rightOpen.value=false;syncCityGround();viewer.camera.flyToBoundingSphere(cityActive.value?new C.BoundingSphere(C.Cartesian3.fromDegrees(121.501,31.236,180),1000):buildingTileset.boundingSphere,{offset:new C.HeadingPitchRange(C.Math.toRadians(cityActive.value?315:20),C.Math.toRadians(top?-90:cityActive.value?-28:-35),cityActive.value?2900:buildingTileset.boundingSphere.radius*1.8),duration:1.2})}
async function removeModel(){buildingSeq++;buildingBusy.value=false;await clearBuildings();activeScene.value='';modelFocused.value=false;buildingStatus.value='模型已卸载';tileTracker.reset('model');updateStatus();viewer?.scene.requestRender()}
async function clearBuildings(){if(cityBaseLayer)cityBaseLayer.show=false;if(buildingLayer){viewer.dataSources.remove(buildingLayer,true);buildingLayer=null}if(buildingTileset){viewer.scene.primitives.remove(buildingTileset);buildingTileset=null}}
async function loadCustomModel(label='自有模型'){
 if(!viewer||disposed)return;let url;try{url=new URL(modelUrl.value.trim(),location.origin);if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw Error('请填写 HTTP(S) 或本地模型地址')}catch(e){buildingStatus.value=e.message;return}
 const seq=++buildingSeq;cityGroundSeq++;cityGroundOffset=0;tileTracker.reset('model');tileTracker.update('model',1);updateStatus();buildingBusy.value=true;regionalManager?.update({enabled:false});buildingStatus.value='3D Tiles 正在加载…';let tileset
 try{tileset=await withDeadline(C.Cesium3DTileset.fromUrl(url.href,{maximumScreenSpaceError:{fast:16,balanced:8,fine:3}[quality.value],skipLevelOfDetail:true,cacheBytes:256*1024*1024,maximumCacheOverflowBytes:128*1024*1024}),20000,t=>t.destroy());if(disposed||seq!==buildingSeq){tileset.destroy();return}await clearBuildings();buildingTileset=viewer.scene.primitives.add(tileset);tileset.show=buildingsVisible.value;tileset.imageBasedLighting.imageBasedLightingFactor=new C.Cartesian2(1,1);activeScene.value=label;modelFocused.value=true;syncCityGround();if(marker){viewer.entities.remove(marker);marker=null}offsetModel();weatherVisible.value=false;rightOpen.value=false;selectedPoint.value=null;stopTour();let seen=false;tileset.loadProgress.addEventListener((pending,processing)=>{if(!disposed&&seq===buildingSeq){tileTracker.update('model',pending+processing);updateStatus()}});tileset.allTilesLoaded.addEventListener(()=>{if(!disposed&&seq===buildingSeq){tileTracker.update('model',0);updateStatus()}});tileset.tileVisible.addEventListener(()=>{if(disposed||seq!==buildingSeq)return;if(!seen){seen=true;buildingStatus.value=label+' · 建筑模型已显示，细节按需加载';viewer.scene.requestRender()}});tileset.tileFailed.addEventListener(e=>{if(!disposed&&seq===buildingSeq){tileTracker.fail('model');updateStatus();buildingStatus.value=label+' · 部分模型瓦片不可用，可重试'}});await viewer.zoomTo(tileset,new C.HeadingPitchRange(C.Math.toRadians(20),C.Math.toRadians(-35),tileset.boundingSphere.radius*1.5));if(disposed||seq!==buildingSeq)return;buildingStatus.value=seen?label+' · 建筑模型已显示':label+' · 正在加载模型瓦片…';coords.value=label+' · 原始地理位置';if(cityActive.value)alignCityGround();viewer.scene.requestRender()}catch(e){if(tileset&&!tileset.isDestroyed()&&tileset!==buildingTileset)tileset.destroy();if(!disposed&&seq===buildingSeq){tileTracker.update('model',0);tileTracker.fail('model');updateStatus();buildingStatus.value='模型加载失败：'+e.message}}finally{if(!disposed&&seq===buildingSeq)buildingBusy.value=false}
}
watch(buildingsVisible,v=>{if(buildingLayer)buildingLayer.show=v;if(buildingTileset)buildingTileset.show=v&&viewer.camera.positionCartographic.height<60000;viewer?.scene.requestRender()})

const cycleLabel=computed(()=>{const c=props.info.initCycle||'';return c.length===10?`${c.slice(0,4)}-${c.slice(4,6)}-${c.slice(6,8)} ${c.slice(8)}:00`:c||'--'})
const variableName=computed(()=>variables.value.find(v=>v.key===variable.value)?.name||'降水')
const selectedName=computed(()=>mode.value==='probability'?'集合降水概率':variableName.value)
const leadIndex=computed(()=>Math.max(0,leads.value.indexOf(lead.value)))
const scaleMin=computed(()=>mode.value==='probability'||variable.value==='tp'?0:field.value.statistics?.minimum??0)
const scaleMax=computed(()=>mode.value==='probability'?100:field.value.statistics?.maximum??1)
const num=v=>Number.isFinite(v)?v.toFixed(1):'--'
const fmt=v=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'--'

function home(){ if(buildingTileset)removeModel();regionalManager?.update({enabled:false});if(baseLayer){baseLayer.show=true;baseLayer.brightness=.8}if(cityBaseLayer)cityBaseLayer.show=false;modelFocused.value=false;weatherVisible.value=true;placesVisible.value=true;boundariesVisible.value=true;rightOpen.value=false;stopTour();viewer?.camera.flyTo({destination:C.Cartesian3.fromDegrees(105,32,14000000),orientation:{heading:0,pitch:-Math.PI/2,roll:0},duration:1.5}) }
function stopTour(){touring.value=false;clearInterval(tourTimer);viewer?.camera.cancelFlight()}
function toggleTour(){if(touring.value){stopTour();return}touring.value=true;tourIndex=0;const stops=[{lon:105,lat:32,height:14000000},...provinces.value.filter(p=>['四川','广东','北京','浙江'].some(n=>p.name.includes(n))).map(p=>({...p,height:1700000}))];const fly=()=>{if(!viewer||disposed)return;const p=stops[tourIndex++%stops.length];viewer.camera.flyTo({destination:C.Cartesian3.fromDegrees(p.lon,p.lat,p.height),duration:2.5})};fly();tourTimer=setInterval(fly,tourInterval.value)}
function fullscreen(){emit('toggle-fullscreen')}
function stopPlayback(){playing.value=false;clearTimeout(playTimer)}
function schedule(){clearTimeout(playTimer);if(playing.value&&!disposed)playTimer=setTimeout(()=>{if(loading.value){schedule();return}step(1)},speed.value)}
function togglePlayback(){if(playing.value)stopPlayback();else{playing.value=true;schedule()}}
function step(direction){if(!leads.value.length)return;let i=leadIndex.value+direction;if(i<0)i=leads.value.length-1;if(i>=leads.value.length)i=0;lead.value=leads.value[i];if(accumulation.value==='24h'&&lead.value<24)accumulation.value='6h'}
function scrub(e){stopPlayback();lead.value=leads.value[Number(e.target.value)];if(lead.value<24&&accumulation.value==='24h')accumulation.value='6h'}
function drawField(data){const texture=rasterize(data.points,data.palette,scaleMin.value,scaleMax.value,mode.value==='forecast'&&variable.value==='tp',smooth.value);const provider=new C.SingleTileImageryProvider({url:texture.image.toDataURL(),rectangle:C.Rectangle.fromDegrees(...texture.bounds),tileWidth:texture.image.width,tileHeight:texture.image.height});const next=viewer.imageryLayers.addImageryProvider(provider);next.alpha=opacity.value;next.show=weatherVisible.value;next.minificationFilter=smooth.value?C.TextureMinificationFilter.LINEAR:C.TextureMinificationFilter.NEAREST;next.magnificationFilter=smooth.value?C.TextureMagnificationFilter.LINEAR:C.TextureMagnificationFilter.NEAREST;if(weatherLayer)viewer.imageryLayers.remove(weatherLayer,true);weatherLayer=next;viewer.scene.requestRender()}
async function loadField(){if(!viewer||disposed)return;const seq=++fieldSeq;loading.value=true;error.value='';if(weatherLayer)weatherLayer.show=false;const key=[props.info.initCycle,mode.value,variable.value,lead.value,accumulation.value,threshold.value].join(':');try{let data=cache.get(key);if(!data){if(mode.value==='probability'){const e=await api.ensemble(lead.value,threshold.value,2);if(!e.available)throw new Error(e.message||'当前批次没有配套集合数据');data={...e,...e.probability,name:'集合降水概率',palette:e.palette}}else data=variable.value==='tp'?await api.overview(lead.value,accumulation.value,2):await api.variableField(variable.value,lead.value,2);if(seq!==fieldSeq||disposed)return;cache.set(key,data);if(cache.size>8)cache.delete(cache.keys().next().value)}if(seq!==fieldSeq||disposed)return;field.value=data;drawField(data)}catch(e){if(seq===fieldSeq&&!disposed){error.value=e.message;field.value={};stopPlayback()}}finally{if(seq===fieldSeq&&!disposed){loading.value=false;schedule()}}}
async function queryPoint(lon,lat,label=''){if(lon<70||lon>140||lat<12||lat>56){coords.value='该位置超出当前预报覆盖范围（70–140°E，12–56°N）';return}openAnalysis('point');const seq=++pointSeq;selectedPoint.value={lon,lat};locationLabel.value=label||`${lon.toFixed(2)}°E / ${lat.toFixed(2)}°N`;pointLoading.value=true;pointError.value='';chart?.clear();if(marker)viewer.entities.remove(marker);marker=viewer.entities.add({position:C.Cartesian3.fromDegrees(lon,lat,1000),point:{heightReference:C.HeightReference.CLAMP_TO_GROUND,pixelSize:10,color:C.Color.WHITE,outlineColor:C.Color.fromCssColorString('#38d9ef'),outlineWidth:3,disableDepthTestDistance:Infinity}});try{const data=await api.point(lon,lat,variable.value);if(seq!==pointSeq||disposed)return;await nextTick();if(!chart)chart=echarts.init(chartEl.value);chart.setOption({backgroundColor:'transparent',grid:{left:42,right:8,top:16,bottom:32},tooltip:{trigger:'axis'},xAxis:{type:'category',data:data.series.map(p=>'+'+p.leadHour+'h'),axisLabel:{color:'#92aac5',fontSize:10}},yAxis:{type:'value',name:data.variable?.unit,axisLabel:{color:'#92aac5',fontSize:10},splitLine:{lineStyle:{color:'#253c53'}}},series:[{type:'line',data:data.series.map(p=>p.value),showSymbol:false,lineStyle:{color:'#58d8ef',width:2},areaStyle:{color:'rgba(60,181,222,.14)'}}]});chart.resize()}catch(e){if(seq===pointSeq&&!disposed)pointError.value=e.message}finally{if(seq===pointSeq&&!disposed)pointLoading.value=false}}
function selectRegion(p){if(cityBaseLayer)cityBaseLayer.show=false;modelFocused.value=false;stopTour();viewer.camera.flyToBoundingSphere(new C.BoundingSphere(C.Cartesian3.fromDegrees(p.lon,p.lat),1000),{offset:new C.HeadingPitchRange(0,C.Math.toRadians(-45),350000),duration:1.5});queryPoint(p.lon,p.lat,p.name)}
function focusRanking(r){const p=provinces.value.find(p=>p.name===r.name);if(p)selectRegion(p)}
async function refresh(){cache.clear();await loadField()}
defineExpose({refresh})
watch([mode,variable,lead,accumulation,threshold],loadField)
watch(variable,()=>{if(selectedPoint.value)queryPoint(selectedPoint.value.lon,selectedPoint.value.lat,locationLabel.value)})
watch(weatherVisible,v=>{if(weatherLayer){weatherLayer.show=v&&!loading.value&&!error.value;viewer.scene.requestRender()}})
watch(boundariesVisible,v=>{if(boundaries){boundaries.show=v;viewer.scene.requestRender()}})
watch(placesVisible,v=>{if(places){places.show=v;viewer.scene.requestRender()}})
watch(opacity,v=>{if(weatherLayer){weatherLayer.alpha=v;viewer.scene.requestRender()}})
watch([regionalEnabled,buildingsVisible],updateRegionalBuildings)
watch(speed,schedule)
watch(tourInterval,()=>{if(touring.value){stopTour();toggleTour()}})
watch(rightTab,async()=>{await nextTick();chart?.resize()})
watch(smooth,()=>{if(field.value.points&&!loading.value)drawField(field.value)})
watch(basemap,loadBasemap)
watch(terrainEnabled,loadTerrain)
watch(rightOpen,async()=>{await nextTick();chart?.resize()})
onMounted(async()=>{
  try{
    viewer=new C.Viewer(globe.value,{baseLayer:false,terrainProvider:new C.EllipsoidTerrainProvider(),animation:false,timeline:false,baseLayerPicker:false,geocoder:false,homeButton:false,sceneModePicker:false,navigationHelpButton:false,fullscreenButton:false,infoBox:false,selectionIndicator:false,requestRenderMode:true,maximumRenderTimeChange:Infinity})
    viewer.clock.currentTime=C.JulianDate.fromIso8601('2026-06-21T04:00:00Z');viewer.clock.shouldAnimate=false;
    viewer.scene.globe.baseColor=C.Color.fromCssColorString('#102a40');viewer.scene.backgroundColor=C.Color.fromCssColorString('#050f1e');viewer.scene.globe.enableLighting=false;viewer.scene.skyAtmosphere.show=false;viewer.scene.light=new C.SunLight({intensity:2});viewer.scene.fog.enabled=false
    viewer.camera.setView({destination:C.Cartesian3.fromDegrees(105,32,14000000),orientation:{heading:0,pitch:-Math.PI/2,roll:0}})
    viewer.scene.postProcessStages.fxaa.enabled=true;viewer.resolutionScale=Math.min(window.devicePixelRatio||1,1.5);viewer.scene.screenSpaceCameraController.minimumZoomDistance=100;
    applyQuality();viewer.scene.globe.preloadSiblings=false;viewer.scene.globe.tileCacheSize=256;viewer.scene.globe.tileLoadProgressEvent.addEventListener(count=>{if(!disposed){tileTracker.update('globe',count);updateStatus()}});statusTimer=setInterval(updateStatus,500)
    viewer.camera.changed.addEventListener(()=>{heading.value=C.Math.toDegrees(viewer.camera.heading);if(buildingTileset){buildingTileset.show=buildingsVisible.value&&viewer.camera.positionCartographic.height<60000;viewer.scene.requestRender()}})
    const base=await C.TileMapServiceImageryProvider.fromUrl('/cesium/Assets/Textures/NaturalEarthII');if(disposed)return;baseLayer=viewer.imageryLayers.addImageryProvider(base);baseLayer.brightness=.8;baseLayer.saturation=.8;loadBasemap();loadTerrain();initRegionalBuildings()
    boundaries=new C.CustomDataSource('province-boundaries');for(const feature of china.features){const polygons=feature.geometry.type==='MultiPolygon'?feature.geometry.coordinates:[feature.geometry.coordinates];for(const polygon of polygons)for(const ring of polygon)boundaries.entities.add({polyline:{positions:C.Cartesian3.fromDegreesArray(ring.flatMap(p=>[p[0],p[1]])),width:1.1,material:C.Color.fromCssColorString('#83b8cc').withAlpha(.65),clampToGround:true}})}await viewer.dataSources.add(boundaries)
    const [vs,ps,ts]=await Promise.all([api.variables(),api.provinces(),api.timeline()]);if(disposed)return;variables.value=vs;provinces.value=ps;leads.value=[...new Set(ts.map(t=>t.leadHour).filter(h=>h>0))].sort((a,b)=>a-b);if(!leads.value.includes(lead.value))lead.value=leads.value[0]||6
    places=new C.CustomDataSource('province-centres');for(const p of ps)places.entities.add({id:p.name,position:C.Cartesian3.fromDegrees(p.lon,p.lat),point:{heightReference:C.HeightReference.CLAMP_TO_GROUND,pixelSize:3,color:C.Color.fromCssColorString('#cce2ef')},label:{heightReference:C.HeightReference.CLAMP_TO_GROUND,text:p.name,font:'12px sans-serif',fillColor:C.Color.fromCssColorString('#d3e7f3'),outlineColor:C.Color.fromCssColorString('#112337'),outlineWidth:3,style:C.LabelStyle.FILL_AND_OUTLINE,pixelOffset:new C.Cartesian2(0,-12),distanceDisplayCondition:new C.DistanceDisplayCondition(0,25000000),disableDepthTestDistance:Infinity}});await viewer.dataSources.add(places)
    handler=new C.ScreenSpaceEventHandler(viewer.scene.canvas);handler.setInputAction(click=>{stopTour();const picked=viewer.scene.pick(click.position);const province=provinces.value.find(p=>p.name===picked?.id?.id);if(province){selectRegion(province);return}const ray=viewer.camera.getPickRay(click.position),pos=(viewer.scene.pickPositionSupported&&viewer.scene.pickPosition(click.position))||(ray&&viewer.scene.globe.pick(ray,viewer.scene));if(!pos)return;const cart=C.Cartographic.fromCartesian(pos),lon=C.Math.toDegrees(cart.longitude),lat=C.Math.toDegrees(cart.latitude);coords.value=`${lon.toFixed(3)}°E / ${lat.toFixed(3)}°N · 场景高 ${cart.height.toFixed(0)}m`;queryPoint(lon,lat)},C.ScreenSpaceEventType.LEFT_CLICK)
    viewer.scene.canvas.addEventListener('pointerdown',stopTour)
    resizeObserver=new ResizeObserver(()=>{viewer?.resize();chart?.resize()});resizeObserver.observe(screen.value)
    clockTimer=setInterval(()=>now.value=new Date().toLocaleString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'}),1000);now.value=new Date().toLocaleString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'})
    initializing.value=false;await loadField();if(offlineStart)await openCity(true);api.risk(2).then(r=>{if(!disposed)risk.value=r}).catch(e=>{if(!disposed)riskError.value=e.message})
  }catch(e){if(!disposed){initializing.value=false;error.value='场景初始化失败：'+e.message}}
})
onBeforeUnmount(()=>{disposed=true;clearInterval(regionalTimer);regionalMoveEnd?.();regionalManager?.dispose();cityGroundSeq++;buildingSeq++;fieldSeq++;pointSeq++;mapSeq++;terrainSeq++;stopPlayback();stopTour();clearInterval(clockTimer);clearInterval(statusTimer);resizeObserver?.disconnect();chart?.dispose();handler?.destroy();if(viewer&&!viewer.isDestroyed()){viewer.scene.canvas.removeEventListener('pointerdown',stopTour);viewer.destroy()}cache.clear()})
